import {Chess} from './chess.js';
import {evaluate} from './engine.js';
import {addIncrement,putArchive,captureSummary} from './session.js';
const $=id=>document.getElementById(id),pieces={w:{k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'},b:{k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'}},names={k:'king',q:'queen',r:'rook',b:'bishop',n:'knight',p:'pawn'};
let game=new Chess(),mode='play',human='w',flipped=false,level=2,selected=null,hintMove=null,busy=false,view=-1,ended='',clockLimit=0,clocks={w:0,b:0},lastTick=performance.now(),lessonIndex=0,puzzleIndex=0,puzzleSolved=false,requestId=0,worker,stats={games:0,puzzles:0},counted=false;
let increment=0,paused=false,soundOn=false,showLegal=true,settleAnalysis=null,analysisTimer=null,gameId=crypto.randomUUID(),lastResult='',savedGames=[],parked=null,solvedIds=[],audioContext;
const lessons=[['Own the center.','The four central squares—e4, d4, e5, and d5—give your pieces room to move. Start with a central pawn, then develop a knight.'],['Bring everyone to the game.','Develop knights and bishops before moving the same piece again. A knight near the center controls more squares than one on the edge.'],['A safe home for your king.','Castle after clearing the pieces between your king and rook. You cannot castle out of check, through check, or into check.'],['Look for forcing moves.','Before choosing a move, look for checks, captures, and threats—for both sides. A forcing move narrows your opponent’s choices.'],['Count the defenders.','Before capturing, compare attackers and defenders. Pawns are roughly 1 point, knights and bishops 3, rooks 5, and queens 9.'],['Turn a pawn into a plan.','A pawn reaching the last rank promotes to a queen, rook, bishop, or knight. In an endgame, activate your king and support passed pawns.']];
const puzzles=[{fen:'6k1/5ppp/8/8/8/8/5PPP/4R1K1 w - - 0 1',title:'The back-rank opportunity',tip:'Black’s pawns leave its king boxed in. Find checkmate in one.'},{fen:'7k/8/5KQ1/8/8/8/8/8 w - - 0 1',title:'Queen and king teamwork',tip:'Bring your queen close, protected by your king. Find checkmate in one.'},{fen:'7k/5K2/6R1/8/8/8/8/8 w - - 0 1',title:'Cut off the escape',tip:'Your king covers g8 and g7. Find a rook move that gives checkmate.'},{fen:'6rk/6pp/7N/8/8/8/8/K7 w - - 0 1',title:'The smothered king',tip:'A knight can jump past the king’s own defenders. Find checkmate in one.'},{fen:'7k/R7/1R6/8/8/8/8/6K1 w - - 0 1',title:'The rook ladder',tip:'One rook cuts off the seventh rank. Use the other to deliver checkmate.'}];
function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');setTimeout(()=>$('toast').classList.remove('visible'),3000)}
function coach(title,text){$('coachTitle').textContent=title;$('coachText').textContent=text}
function save(){try{localStorage.setItem('knight-studio-v1',JSON.stringify({pgn:game.pgn(),fen:game.fen(),mode,human,flipped,level,clockLimit,clocks,ended,stats,counted,puzzleIndex,puzzleSolved,increment,gameId,paused,soundOn,showLegal,parked,solvedIds}));}catch{}}
function cancel(){requestId++;busy=false;clearTimeout(analysisTimer);if(worker)worker.terminate();worker=null;const resolve=settleAnalysis;settleAnalysis=null;if(resolve)resolve(null);$('engineStatus').textContent='Local chess engine · Ready';updateExtras()}
function analyze(fen,depth=3,budget=1400){cancel();busy=true;const id=++requestId;updateExtras();$('engineStatus').textContent='Considering the possibilities…';return new Promise(resolve=>{settleAnalysis=resolve;const fail=()=>{if(id!==requestId)return;cancel();toast('Analysis stopped. Try a hint or resume play.')};try{worker=new Worker('./engine.js',{type:'module'});worker.onmessage=e=>{if(e.data.id!==requestId)return;clearTimeout(analysisTimer);busy=false;settleAnalysis=null;$('engineStatus').textContent=`Local engine · depth ${e.data.moves[0]?.depth||0}`;worker.terminate();worker=null;updateExtras();resolve(e.data.moves)};worker.onerror=fail;analysisTimer=setTimeout(fail,budget+6000);worker.postMessage({id,fen,depth,budget})}catch{fail()}})}
function shownGame(){if(view<0)return game;const h=game.history({verbose:true});return new Chess(view===0?(h[0]?.before||game.fen()):h[view-1].after)}
function render(){const g=shownGame(),history=game.history({verbose:true}),last=view<0?history.at(-1):history[view-1],legal=showLegal&&selected&&view<0?game.moves({square:selected,verbose:true}):[];let html='';for(let i=0;i<64;i++){const f=flipped?7-i%8:i%8,r=flipped?Math.floor(i/8):7-Math.floor(i/8),s='abcdefgh'[f]+(r+1),p=g.get(s),dest=legal.some(m=>m.to===s);html+=`<button class="sq ${(f+r)%2?'light':'dark'} ${p?(p.color==='w'?'whitepiece':'blackpiece'):''} ${last&&(last.from===s||last.to===s)?'last':''} ${selected===s?'selected':''} ${hintMove&&(hintMove.from===s||hintMove.to===s)?'hint':''} ${p?.type==='k'&&p.color===g.turn()&&g.isCheck()?'check':''} ${dest&&p?'capture':''}" data-square="${s}" aria-label="${s}${p?' '+(p.color==='w'?'White':'Black')+' '+names[p.type]:''}${dest?', legal destination':''}">${p?pieces[p.color][p.type]:''}${dest&&!p?'<span class="dot"></span>':''}${i%8===0?`<span class="coord rank">${r+1}</span>`:''}${i>=56?`<span class="coord">${'abcdefgh'[f]}</span>`:''}</button>`}$('board').innerHTML=html;let rows='';for(let i=0;i<history.length;i+=2){rows+=`<div class="moverow"><span>${i/2+1}.</span>${[i,i+1].map(n=>history[n]?`<button data-ply="${n+1}" class="${(view<0?history.length:view)===n+1?'current':''}">${history[n].san}</button>`:'<span></span>').join('')}</div>`}$('history').innerHTML=rows||'<div class="empty"><span>♙</span><b>A fresh board. A fresh start.</b><p>Your moves will appear here.</p></div>';$('moveCount').textContent=`Move ${view<0?history.length:view}${view>=0?' · review':''}`;if(view<0)$('history').scrollTop=$('history').scrollHeight;const score=evaluate(g);$('evalfill').style.height=`${Math.max(5,Math.min(95,50+score/30))}%`;$('evalfill').parentElement.title=`Position estimate: ${(score/100).toFixed(1)} pawns for White`;
let status=ended|| (game.isCheckmate()?`${game.turn()==='w'?'Black':'White'} wins by checkmate`:game.isStalemate()?'Draw by stalemate':game.isThreefoldRepetition()?'Draw by repetition':game.isInsufficientMaterial()?'Draw · insufficient material':game.isDraw()?'Draw':`${game.turn()==='w'?'White':'Black'} to move${game.isCheck()?' · Check':''}`);$('turnStatus').textContent=view>=0?'Reviewing · return to latest to play':status;if(game.isGameOver()&&!ended){ended=status;if(!counted&&mode!=='puzzle'&&mode!=='review'){stats.games++;counted=true}if(mode!=='puzzle')coach('A game to learn from.',status+'. Use the arrows in move history to revisit your decisions.');save()}
const titles={play:["Let's play chess.",'A worthy opponent. A little room to grow.','Play against AI'],learn:['A better move, together.','Take your time. Your coach is in your corner.','Learn with a coach'],local:['Share the board.','Two players. One good game.','Two players'],puzzle:['Find the winning idea.','Small challenges. Lasting progress.','Puzzle practice'],review:['See the game differently.','Revisit every decision. Discover the next idea.','Game review']};$('title').textContent=titles[mode][0];$('subtitle').textContent=titles[mode][1];$('modeLabel').textContent=titles[mode][2];$('levelLabel').textContent=mode==='puzzle'?`Puzzle ${puzzleIndex+1} / ${puzzles.length}`:['','Beginner','Club player','Advanced','Expert'][level];document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('coachToggle').textContent=mode==='learn'?'Ask for a hint →':mode==='review'?'Import FEN / PGN →':'Turn on coach →';$('opponent').textContent=mode==='local'?'Black':mode==='puzzle'?'The challenge':'Atlas';$('opponentDesc').textContent=mode==='local'?'Player two':mode==='puzzle'?'Find checkmate in one':`Your AI sparring partner · ${human==='w'?'Black':'White'}`;$('yourName').textContent=mode==='local'?'White':mode==='review'?'Analysis board':`You · ${human==='w'?'White':'Black'}`;$('stats').textContent=`${stats.games} games completed · ${stats.puzzles} puzzles solved`;updateClocks();updateExtras();maybeResult();}
function updateClocks(){function fmt(c){if(!clockLimit)return '∞';let n=Math.ceil(clocks[c]);return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}const top=mode==='local'?'b':human==='w'?'b':'w';$('blackClock').textContent=fmt(top);$('whiteClock').textContent=fmt(top==='w'?'b':'w');$('blackClock').classList.toggle('activeclock',game.turn()===top&&!ended);$('whiteClock').classList.toggle('activeclock',game.turn()!==top&&!ended);$('blackClock').classList.toggle('lowtime',!!clockLimit&&clocks[top]<30);$('whiteClock').classList.toggle('lowtime',!!clockLimit&&clocks[top==='w'?'b':'w']<30);$('blackClock').title=$('whiteClock').title=clockLimit?`${increment} seconds added per move`:'Unlimited time'}
function explain(m){if(m.san.includes('#'))return 'Checkmate: the king is attacked and has no legal escape.';if(m.flags.includes('k')||m.flags.includes('q'))return 'Castling moves your king toward safety and brings your rook into the game.';if(m.promotion)return 'Your pawn reached the last rank and promoted. This is why passed pawns can decide endgames.';if(m.flags.includes('e'))return 'En passant: this pawn captures the pawn that just advanced two squares beside it.';if(m.captured)return `This captures a ${names[m.captured]}. Check how many opposing pieces can recapture on ${m.to}.`;if(m.san.includes('+'))return 'This gives check, so your opponent must respond to the threat against the king.';if('nb'.includes(m.piece)&&game.history().length<16)return `Your ${names[m.piece]} joins the game. Developing your minor pieces helps connect your rooks and prepare castling.`;if(['e4','d4','e5','d5'].includes(m.to))return 'This move occupies the center. Central space gives your pieces more routes to attack and defend.';return `Your ${names[m.piece]} moves to ${m.to}. Before the next move, scan for checks, captures, and unprotected pieces.`}
async function doMove(from,to,promotion){if(busy||paused||ended||view>=0)return;let legal=game.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!legal.length)return;if(legal.some(m=>m.promotion)&&!promotion){$('promotionChoices').innerHTML=['q','r','b','n'].map(p=>`<button data-promo="${p}" aria-label="${names[p]}">${pieces[game.turn()][p]}</button>`).join('');$('promotion').showModal();$('promotionChoices').onclick=e=>{const p=e.target.dataset.promo;if(p){$('promotion').close();doMove(from,to,p)}};return}const before=game.fen();let m=game.move({from,to,promotion:promotion||'q'});if(mode==='puzzle'&&!game.isCheckmate()){game.undo();selected=null;render();coach('Keep looking.',puzzles[puzzleIndex].tip+' That move does not give checkmate.');return}selected=null;hintMove=null;view=-1;clocks=addIncrement(clocks,m.color,increment,!!clockLimit);playSound(m);if(clockLimit&&mode!=='puzzle')save();if(mode==='puzzle'){puzzleSolved=true;if(!solvedIds.includes(puzzleIndex)){solvedIds.push(puzzleIndex);stats.puzzles++;}coach('Beautiful. Checkmate!',explain(m)+' Choose Next puzzle to try another pattern.');$('lessonNext').textContent='Next puzzle →';render();save();return}if(mode==='learn'){coach(`You played ${m.san}.`,explain(m));render();const ranked=await analyze(before,3,1000);if(!ranked||game.fen()!==m.after)return;const actual=ranked.find(x=>x.from===from&&x.to===to&&(!x.promotion||x.promotion===(promotion||'q')));const loss=actual&&ranked.length?ranked[0].score-actual.score:0;if(loss>140)coach(`A moment to reflect: ${m.san}`,`${explain(m)} The engine prefers ${ranked[0].san}; its short search estimates your move gives up about ${Math.min(99,loss/100).toFixed(1)} pawns. Try Take back to compare.`);else coach(`${loss<35?'A promising move':'A playable idea'}: ${m.san}`,explain(m)+' This is a short engine estimate, not a full-game judgment.');}render();save();await aiTurn()}
async function aiTurn(){if(!['play','learn'].includes(mode)||game.turn()===human||game.isGameOver()||ended||view>=0||busy||paused||document.hidden||document.querySelector('dialog[open]'))return;const fen=game.fen(),ranked=await analyze(fen,level,level===4?2800:1300);if(!ranked||game.fen()!==fen||ended||paused||view>=0||document.querySelector('dialog[open]')||!['play','learn'].includes(mode))return;const m=level===1?ranked[Math.floor(Math.random()*Math.min(5,ranked.length))]:ranked[0];if(m){const played=game.move(m);clocks=addIncrement(clocks,played.color,increment,!!clockLimit);playSound(played);selected=null;hintMove=null;render();save()}}
$('board').onclick=e=>{const s=e.target.closest('[data-square]')?.dataset.square;if(!s||busy||paused||ended||view>=0||mode==='review'||performance.now()<suppressClickUntil)return;if(['play','learn'].includes(mode)&&game.turn()!==human)return;if(selected&&game.moves({square:selected,verbose:true}).some(m=>m.to===s)){doMove(selected,s);return}selected=game.get(s)?.color===game.turn()?s:null;hintMove=null;render()};
async function hint(){if(busy){toast('Let the engine finish its move.');return}const g=shownGame();if(g.isGameOver()){toast('This position has ended.');return}const fen=g.fen();const moves=await analyze(fen,3,1800);if(!moves||shownGame().fen()!==fen)return;hintMove=moves[0];if(hintMove){const probe=new Chess(fen),m=probe.move(hintMove);coach(`Consider ${hintMove.san}.`,`${names[m.piece][0].toUpperCase()+names[m.piece].slice(1)} ${m.from} → ${m.to}. ${explain(m)} The gold arrow shows the idea.`);render();showAlternatives(moves)}}
$('hint').onclick=hint;$('flip').onclick=()=>{flipped=!flipped;render();save()};$('undo').onclick=()=>{if(clockLimit&&Math.min(clocks.w,clocks.b)<=0){toast('Start a new game to reset the clocks.');return}if(mode==='review'){navigate(Math.max(0,(view<0?game.history().length:view)-1));return}cancel();ended='';if(mode==='puzzle'){game.load(puzzles[puzzleIndex].fen);puzzleSolved=false}else{game.undo();if(['play','learn'].includes(mode)&&game.turn()!==human&&game.history().length)game.undo()}selected=null;hintMove=null;view=-1;lastTick=performance.now();coach('Another way to see it.','Try a different move and compare the resulting position. Clocks are not refunded for takebacks.');render();save();aiTurn()};
function resignGame(){if(ended||mode==='review'||mode==='puzzle')return;cancel();ended=`${mode==='local'?(game.turn()==='w'?'White':'Black'):'You'} resigned`;if(!counted){stats.games++;counted=true}coach('Every game teaches you something.','Review your moves, or start a fresh game when you are ready.');render();save()};
$('resign').onclick=()=>{if(!ended&&!['review','puzzle'].includes(mode))$('resignDialog').showModal()};$('keepPlaying').onclick=()=>$('resignDialog').close();$('confirmResign').onclick=()=>{$('resignDialog').close();resignGame()};
function navigate(n){if(busy)cancel();const len=game.history().length;view=n>=len?-1:Math.max(0,n);selected=null;hintMove=null;render();if(view<0)aiTurn()}
$('history').onclick=e=>{const p=e.target.dataset.ply;if(p)navigate(+p)};$('first').onclick=()=>navigate(0);$('prev').onclick=()=>navigate((view<0?game.history().length:view)-1);$('next').onclick=()=>navigate((view<0?game.history().length:view)+1);$('last').onclick=()=>navigate(game.history().length);
function openSetup(){$('modeInput').value=['play','learn','local'].includes(mode)?mode:'play';$('difficulty').value=level;$('color').value=human;$('time').value=clockLimit;$('increment').value=increment;$('setup').showModal()}
$('new').onclick=openSetup;$('settings').onclick=openSetup;$('start').onclick=()=>{archiveCurrent();cancel();gameId=crypto.randomUUID();lastResult='';paused=false;parked=null;game=new Chess();mode=$('modeInput').value;level=+$('difficulty').value;human=$('color').value;if(human==='random')human=Math.random()<.5?'w':'b';flipped=human==='b';clockLimit=+$('time').value;increment=+$('increment').value;clocks={w:clockLimit,b:clockLimit};lastTick=performance.now();ended='';counted=false;selected=null;hintMove=null;view=-1;coach(mode==='learn'?'Let’s build good habits.':'Every move is a possibility.',mode==='learn'?'Click a piece to see its legal moves. I’ll explain your moves and flag alternatives worth exploring. Start by claiming the center.':'Control the center, develop your pieces, and find a safe home for your king. Ready when you are.');lessonIndex=0;showLesson();render();save();aiTurn()};
function showLesson(){const l=lessons[lessonIndex];$('lessonEyebrow').textContent=`CHESS FOUNDATIONS · ${lessonIndex+1} / ${lessons.length}`;$('lessonTitle').textContent=l[0];$('lessonText').textContent=l[1];$('lessonNext').textContent=mode==='review'?'Import FEN / PGN →':'Next lesson →'}
function parkGame(){if(['play','learn','local'].includes(mode)){parked=snapshot();archiveCurrent()}}
function loadPuzzle(){parkGame();cancel();mode='puzzle';human='w';flipped=false;clockLimit=0;paused=false;ended='';view=-1;selected=null;hintMove=null;puzzleSolved=false;game=new Chess(puzzles[puzzleIndex].fen);coach(puzzles[puzzleIndex].title,puzzles[puzzleIndex].tip);$('lessonEyebrow').textContent='TACTICS TRAINING';$('lessonTitle').textContent='One move. One clear idea.';$('lessonText').textContent='Find checkmate. Wrong attempts keep the position unchanged. Each puzzle counts once toward your progress.';$('lessonNext').textContent='Next puzzle →';render();save()}
function switchMode(m){if(m==='puzzle'){loadPuzzle();return}cancel();if(m==='review'){parkGame();mode='review';view=-1;coach('The board has a story.','Use the history arrows, then Get a hint to compare candidate moves. Your active game and its clock are preserved.')}else{if(['review','puzzle'].includes(mode)){if(parked){restoreSnapshot(parked);parked=null}else{game=new Chess();clockLimit=0;ended='';counted=false;gameId=crypto.randomUUID()}}mode=m;view=-1;coach(m==='learn'?'Your coach is in your corner.':'Ready for the next move.',m==='learn'?'I’ll explain your moves and point out alternatives. Ask for a hint to compare up to three candidate moves.':'Look for checks, captures, and threats. Click or drag a piece to make your move.')}selected=null;hintMove=null;lastTick=performance.now();showLesson();render();save();aiTurn()}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>switchMode(b.dataset.mode));$('coachToggle').onclick=()=>mode==='learn'?hint():mode==='review'?$('importDialog').showModal():switchMode('learn');$('lessonNext').onclick=()=>{if(mode==='puzzle'){puzzleIndex=(puzzleIndex+1)%puzzles.length;loadPuzzle()}else if(mode==='review')$('importDialog').showModal();else{lessonIndex=(lessonIndex+1)%lessons.length;showLesson();if(mode==='learn')coach(lessons[lessonIndex][0],lessons[lessonIndex][1])}};
$('export').onclick=()=>{const blob=new Blob([game.pgn()||'[Event "Knight Studio"]\n\n*'],{type:'application/x-chess-pgn'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='knight-studio-game.pgn';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Game exported as PGN.')};$('importCancel').onclick=()=>$('importDialog').close();$('importConfirm').onclick=()=>{try{const text=$('importText').value.trim();if(!text)throw Error('Paste a FEN or PGN first.');let g=new Chess();if(/^[prnbqkPRNBQK1-8/]+\s[wb]\s/.test(text))g.load(text);else g.loadPgn(text);parkGame();cancel();game=g;gameId=crypto.randomUUID();ended='';mode='review';clockLimit=0;view=-1;selected=null;hintMove=null;$('importDialog').close();coach('A new position to explore.','Navigate the game history or request a hint to find a candidate move.');render();save()}catch(e){$('importError').textContent='Could not load that position. Check that the FEN or PGN is valid.'}};
setInterval(()=>{const now=performance.now(),delta=(now-lastTick)/1000;lastTick=now;if(clockLimit&&!paused&&!document.hidden&&!ended&&view<0&&!game.isGameOver()&&game.history().length&&['play','learn','local'].includes(mode)&&!document.querySelector('dialog[open]')){clocks[game.turn()]=Math.max(0,clocks[game.turn()]-delta);if(clocks[game.turn()]===0){cancel();ended=`${game.turn()==='w'?'Black':'White'} wins on time`;if(!counted){stats.games++;counted=true}coach('Time is up.',ended+'. Start another game or review your moves.');render()}save()}updateClocks()},250);
function snapshot(){return {id:gameId,pgn:game.pgn(),fen:game.fen(),mode,human,flipped,level,clockLimit,clocks:{...clocks},increment,ended,counted}}
function archiveCurrent(){if(mode==='puzzle'||!game.history().length)return;savedGames=putArchive(savedGames,mode==='review'&&parked?.id===gameId?parked:snapshot());try{localStorage.setItem('knight-library',JSON.stringify(savedGames))}catch{toast('Device storage is full. Export PGN to keep this game.')}}
function restoreSnapshot(s){game=new Chess();if(s.pgn)game.loadPgn(s.pgn);else game.load(s.fen);gameId=s.id||crypto.randomUUID();mode=s.mode||'play';human=s.human||'w';flipped=!!s.flipped;level=s.level||2;clockLimit=s.clockLimit||0;clocks={...s.clocks};increment=s.increment||0;ended=s.ended||'';counted=!!s.counted;view=-1;selected=null;hintMove=null;paused=false;lastTick=performance.now();lastResult=ended?gameId:''}
function showLibrary(){archiveCurrent();$('savedList').replaceChildren();for(const item of savedGames){const row=document.createElement('div');row.className='savedgame';const info=document.createElement('div'),title=document.createElement('b'),detail=document.createElement('small'),button=document.createElement('button');title.textContent=item.ended||`Unfinished · ${item.human==='b'?'Black':'White'}`;detail.textContent=new Date(item.savedAt).toLocaleString();info.append(title,detail);button.textContent=item.ended?'Review →':'Resume →';button.onclick=()=>{archiveCurrent();cancel();restoreSnapshot(item);parked=null;if(ended)mode='review';$('libraryDialog').close();coach('Your game, right where you left it.','Use the move list to review, or continue playing.');showLesson();render();save();aiTurn()};row.append(info,button);$('savedList').append(row)}if(!savedGames.length)$('savedList').textContent='Your games appear here after you make a move.';$('libraryDialog').showModal()}
$('library').onclick=showLibrary;$('libraryClose').onclick=()=>$('libraryDialog').close();
function maybeResult(){if(!ended||mode==='review'||mode==='puzzle'||lastResult===gameId)return;lastResult=gameId;archiveCurrent();$('resultTitle').textContent=ended;$('resultText').textContent=`${Math.ceil(game.history().length/2)} moves played. Your game is saved. Review a key moment or try a rematch.`;if(!document.querySelector('dialog[open]'))$('resultDialog').showModal()}
$('resultReview').onclick=()=>{$('resultDialog').close();switchMode('review')};$('resultNew').onclick=()=>{$('resultDialog').close();openSetup()};
function updateExtras(){if(!$('playState'))return;const reviewing=view>=0||mode==='review';$('playState').textContent=ended|| (reviewing?'Reviewing the board':paused?'Game paused':busy?'Atlas is thinking…':game.turn()===human||mode==='local'?'Your move':'Atlas to move');$('playState').classList.toggle('thinking',busy);$('pause').disabled=ended!==''||['puzzle','review'].includes(mode);$('pause').textContent=paused?'▶ Resume':'Ⅱ Pause';$('hint').disabled=busy;$('undo').disabled=!game.history().length&&mode!=='puzzle';$('resign').disabled=!!ended||['review','puzzle'].includes(mode);$('sound').textContent=soundOn?'♪ Sound on':'♪ Sound off';$('sound').setAttribute('aria-pressed',String(soundOn));$('legalToggle').setAttribute('aria-pressed',String(showLegal));
const g=shownGame(),{captured,balance}=captureSummary(g,view<0?game.history({verbose:true}):game.history({verbose:true}).slice(0,view)),top=mode==='local'?'b':human==='w'?'b':'w',bottom=top==='w'?'b':'w';function caps(c){return captured[c].map(p=>pieces[c==='w'?'b':'w'][p]).join(' ')+(balance*(c==='w'?1:-1)>0?`  +${Math.abs(balance)}`:'')};$('topCaptures').textContent=caps(top);$('bottomCaptures').textContent=caps(bottom);$('topCaptures').title='Pieces captured by '+(top==='w'?'White':'Black');$('bottomCaptures').title='Pieces captured by '+(bottom==='w'?'White':'Black');
const h=game.history(),prefix=h.slice(0,4).join(' ');let opening=h.length?'Opening in progress':'Starting position';if(prefix.startsWith('e4 e5 Nf3 Nc6'))opening=h[4]==='Bb5'?'Ruy Lopez':h[4]==='Bc4'?'Italian Game':'Open Game';else if(prefix.startsWith('e4 c5'))opening='Sicilian Defense';else if(prefix.startsWith('e4 e6'))opening='French Defense';else if(prefix.startsWith('e4 c6'))opening='Caro-Kann Defense';else if(prefix.startsWith('d4 d5 c4'))opening='Queen’s Gambit';else if(h.length>14)opening='Find your next idea';if(mode==='puzzle')opening=`${solvedIds.length} / ${puzzles.length} puzzles mastered`;$('opening').textContent=opening;
const line=$('hintLine');$('hintArrow').style.display=hintMove?'block':'none';if(hintMove){function point(s){const f=s.charCodeAt(0)-97,r=+s[1]-1;return [(flipped?7-f:f)*100+50,(flipped?r:7-r)*100+50]}const a=point(hintMove.from),b=point(hintMove.to);line.setAttribute('x1',a[0]);line.setAttribute('y1',a[1]);line.setAttribute('x2',b[0]);line.setAttribute('y2',b[1])}if(!hintMove)$('alternatives').replaceChildren();$('board').classList.toggle('paused',paused);}
function showAlternatives(moves){$('alternatives').replaceChildren();const label=document.createElement('small');label.textContent='CANDIDATE MOVES · SHORT SEARCH';$('alternatives').append(label);for(const m of moves.slice(0,3)){const b=document.createElement('button');b.textContent=`${m.san}  ${Math.abs(m.score)>90000?(m.score>0?'Mate':'−Mate'):(m.score>=0?'+':'')+(m.score/100).toFixed(1)}`;b.title='Evaluation from the side to move’s perspective';b.onclick=()=>{hintMove=m;render();showAlternatives(moves);const probe=new Chess(shownGame().fen());const played=probe.move(m);coach(`Explore ${m.san}.`,`${m.from} → ${m.to}. ${explain(played)} Scores are estimates from the side to move’s perspective.`)};$('alternatives').append(b)}}
function initAudio(){try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume()}catch{}}
function playSound(m){if(!soundOn)return;try{initAudio();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=m.san.includes('+')||m.san.includes('#')?660:m.captured?260:440;gain.gain.setValueAtTime(.06,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.12);osc.connect(gain).connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.13)}catch{}}
$('sound').onclick=()=>{soundOn=!soundOn;if(soundOn){initAudio();playSound({san:''})}updateExtras();save()};$('legalToggle').onclick=()=>{showLegal=!showLegal;render();save()};$('pause').onclick=()=>{if(ended||['puzzle','review'].includes(mode))return;paused=!paused;if(paused)cancel();lastTick=performance.now();render();save();if(!paused)aiTurn()};
let drag=null,suppressClickUntil=0;
$('board').addEventListener('pointerdown',e=>{const square=e.target.closest('[data-square]')?.dataset.square;if(e.button!==0||!square||busy||paused||ended||view>=0||mode==='review'||(['play','learn'].includes(mode)&&game.turn()!==human)||game.get(square)?.color!==game.turn())return;drag={square,x:e.clientX,y:e.clientY,id:e.pointerId,moved:false};if(soundOn)initAudio()});
$('board').addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7){drag.moved=true;selected=drag.square;hintMove=null;render();$('board').setPointerCapture(e.pointerId);const ghost=document.createElement('div');ghost.id='dragPiece';ghost.textContent=pieces[game.turn()][game.get(drag.square).type];ghost.className=game.turn()==='w'?'whiteghost':'blackghost';document.body.append(ghost)}if(drag.moved){const ghost=$('dragPiece');ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';e.preventDefault()}});
function stopDrag(e){if(!drag)return;const current=drag;drag=null;$('dragPiece')?.remove();if(current.moved){suppressClickUntil=performance.now()+350;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-square]')?.dataset.square;if(e.type==='pointerup'&&target&&game.moves({square:current.square,verbose:true}).some(m=>m.to===target))doMove(current.square,target);else{selected=null;render()}}}
$('board').addEventListener('pointerup',stopDrag);$('board').addEventListener('pointercancel',stopDrag);
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;const key=e.key.toLowerCase();if(key==='h'){$('hint').click();e.preventDefault()}if(key==='f'){$('flip').click();e.preventDefault()}if(key==='arrowleft'){navigate((view<0?game.history().length:view)-1);e.preventDefault()}if(key==='arrowright'){navigate((view<0?game.history().length:view)+1);e.preventDefault()}if(key==='escape'){selected=null;hintMove=null;render()}});
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden){cancel();save()}else aiTurn()});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('close',()=>{lastTick=performance.now();aiTurn()}));
window.addEventListener('pagehide',()=>{save();archiveCurrent()});
try{savedGames=JSON.parse(localStorage.getItem('knight-library')||'[]');const s=JSON.parse(localStorage.getItem('knight-studio-v1'));if(s){increment=s.increment||0;gameId=s.gameId||crypto.randomUUID();paused=!!s.paused;soundOn=!!s.soundOn;showLegal=s.showLegal!==false;parked=s.parked||null;if(!parked&&s.mode==='puzzle'){const legacy=JSON.parse(localStorage.getItem('knight-parked-game')||'null');if(legacy)parked={...legacy,id:crypto.randomUUID(),mode:'play',level:s.level||2,increment:0}}solvedIds=s.solvedIds||[];if(s.pgn)game.loadPgn(s.pgn);else if(s.fen)game.load(s.fen);({mode,human,flipped,level,clockLimit,clocks,ended,stats,counted,puzzleIndex,puzzleSolved}=s);if(mode==='puzzle'){coach(puzzleSolved?'Puzzle complete':puzzles[puzzleIndex].title,puzzles[puzzleIndex].tip);$('lessonNext').textContent='Next puzzle →'}else if(game.history().length)coach('Welcome back to the board.','Your game has been restored. Pick up where you left off, or review the moves so far.')}}catch{game=new Chess();mode='play';stats={games:0,puzzles:0}}
if(mode==='review')showLesson();render();aiTurn();
